/// <summary>
///    The <c>METCustFreeInvoiceWFApprovalEventHandler_Extension</c> class is used to handle events related to the workflow approval element.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[ExtensionOf(classStr(CustFreeInvoiceWFApprovalEventHandler))]
public final class METCustFreeInvoiceWFApprovalEventHandler_Extension
{
}

Method.Source:
/// <summary>
///    Sets the <c>WorkflowApprovalState</c> fields on the <c>CustInvoiceTable</c> table to the
///    <c>CustFreeInvoiceWFApprovalState::Approved</c> enumeration value.
/// </summary>
/// <param name="_workflowElementEventArgs">
///    An instance of the <c>WorkflowElementEventArgs</c> class.
/// </param>
/// <remarks>
///    This method is called from the workflow framework when the approval element is completed.
/// </remarks>
public void completed(WorkflowElementEventArgs _workflowElementEventArgs)
{
    CustInvoiceTable    custInvoiceTable;
    RecId               invoiceRecId;
    SalesParameters     salesParameters;
    TransDate           newTransDate;
    PaymTerm            paymTerm;

    next completed(_workflowElementEventArgs);

    invoiceRecId = _workflowElementEventArgs.parmWorkflowContext().parmRecId();

    if (invoiceRecId)
    {
        custInvoiceTable = CustInvoiceTable::findRecId(invoiceRecId);

        if (custInvoiceTable && custInvoiceTable.Posted == NoYes::No)
        {
            salesParameters = SalesParameters::find();

            switch (salesParameters.METVendInvoicePostingDateAutoAdjustment)
            {
                case METVendInvoicePostingDateAutoAdjustment::NoChange:
                    break;

                case METVendInvoicePostingDateAutoAdjustment::AlwaysChangeToSystemDate:
                    newTransDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
                    break;

                default:
                    break;
            }

            if ((newTransDate != dateNull()) && (newTransDate != custInvoiceTable.InvoiceDate))
            {
                ttsbegin;
                custInvoiceTable.selectForUpdate(true);
                custInvoiceTable.InvoiceDate = newTransDate;

                paymTerm = PaymTerm::find(custInvoiceTable.Payment);
                custInvoiceTable.DueDate = paymTerm.due(newTransDate, custInvoiceTable.paymDayId());
                if (custInvoiceTable.validateWrite())
                {
                    custInvoiceTable.update();
                }
                else
                {
                    throw Exception::Error;
                }
                ttscommit;
            }
        }
    }
}
